insert into public.settings (key, value, description) values ('report_email', '{"subject":"CS QA Report {WEEK} | {CAM_NAME}","body_html":"<p>Hello {CAM_NAME},</p><p>Here is the <a href=\"{REPORT_LINK}\">Quality Assurance Report</a> for the audits completed during <strong>{WEEK} ({WEEK_RANGE})</strong>. Please reach out to us if you have any questions.</p><p>Have an amazing week!</p><p>Thank you,<br>Regards,<br>{SENDER_NAME}<br>Quality Assurance | FULL Creative</p>","sender_name":"Ramitha V","reply_to":"","cc_lead":true,"extra_cc":"","send_on_publish":false}'::jsonb, 'Weekly QA report email sent to each CAM (CC: Team Lead) when a week is published') on conflict (key) do nothing;
